import{_ as a,o as n,a as p,b as c}from"./app.BGziXukh.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据搬出","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/reg_data_store"},{"text":"store","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/store"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/store.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/store.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":3,"title":"矢量数据寄存器搬出","slug":"矢量数据寄存器搬出","link":"#矢量数据寄存器搬出"},{"level":3,"title":"掩码寄存器搬出","slug":"掩码寄存器搬出","link":"#掩码寄存器搬出"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"矢量数据寄存器搬出","slug":"矢量数据寄存器搬出-1","link":"#矢量数据寄存器搬出-1"},{"level":3,"title":"掩码寄存器搬出","slug":"掩码寄存器搬出-1","link":"#掩码寄存器搬出-1"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":3,"title":"矢量数据寄存器搬出","slug":"矢量数据寄存器搬出-2","link":"#矢量数据寄存器搬出-2"},{"level":3,"title":"掩码寄存器搬出","slug":"掩码寄存器搬出-2","link":"#掩码寄存器搬出-2"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"},{"level":3,"title":"正常搬出","slug":"正常搬出","link":"#正常搬出"},{"level":3,"title":"交织搬出","slug":"交织搬出","link":"#交织搬出"},{"level":3,"title":"掩码寄存器搬出","slug":"掩码寄存器搬出-3","link":"#掩码寄存器搬出-3"}],"lastUpdated":1794468776000}'),e={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/store.md"};function l(t,s,d,o,r,i){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>store</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_data_store.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p><code>store</code>用于将<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>中的数据搬出到Unified Buffer（UB）Tensor。接口支持以下两类源寄存器：</p><ul><li><a href="#%E7%9F%A2%E9%87%8F%E6%95%B0%E6%8D%AE%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA">矢量数据寄存器搬出</a>：通过<code>store_sideband_mode</code>选择正常搬出、首元素搬出、交织搬出或压缩搬出。</li><li><a href="#%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA">掩码寄存器搬出</a>：使用<code>reg_tensor&lt;bool&gt;</code>作为单源操作数，通过<code>direct</code>按原样搬出掩码比特，或通过<code>pack</code>隔位压缩搬出。两种模式均不读取<code>src.mask</code>。</li></ul><p>接口支持以下两种寻址方式：</p><ul><li>传入<code>coord</code>时，从<code>tensor.engine() + tensor.layout()(coord)</code>对应的元素开始写入。</li><li>不传入<code>coord</code>时，从<code>tensor</code>起始位置开始写入。</li></ul><p><code>intlv</code>模式使用双源操作数重载，其他模式使用单源操作数重载。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><h3 id="矢量数据寄存器搬出">矢量数据寄存器搬出<a class="header-anchor" href="#矢量数据寄存器搬出">​</a></h3><p><a id="store-single-source"></a></p><ul><li><p>单源操作数，指定坐标：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">store_sideband_mode</span><span class="w"> </span><span class="n">sideband_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">store_sideband_mode</span><span class="o">::</span><span class="n">direct</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">RegDataType</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">store</span><span class="p">(</span>
<span class="w">    </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
</code></pre></div></li><li><p>单源操作数，从Tensor起始位置搬出：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">store_sideband_mode</span><span class="w"> </span><span class="n">sideband_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">store_sideband_mode</span><span class="o">::</span><span class="n">direct</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">RegDataType</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">store</span><span class="p">(</span>
<span class="w">    </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
</code></pre></div></li><li><p>双源操作数，指定坐标：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">store_sideband_mode</span><span class="w"> </span><span class="n">sideband_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">store_sideband_mode</span><span class="o">::</span><span class="n">intlv</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">RegDataType</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">store</span><span class="p">(</span>
<span class="w">    </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src1</span><span class="p">)</span>
</code></pre></div></li><li><p>双源操作数，从Tensor起始位置搬出：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">store_sideband_mode</span><span class="w"> </span><span class="n">sideband_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">store_sideband_mode</span><span class="o">::</span><span class="n">intlv</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">RegDataType</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">store</span><span class="p">(</span>
<span class="w">    </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src1</span><span class="p">)</span>
</code></pre></div></li></ul><h3 id="掩码寄存器搬出">掩码寄存器搬出<a class="header-anchor" href="#掩码寄存器搬出">​</a></h3><p>复用上述<a href="#store-single-source">两个单源操作数原型</a>，分别支持指定<code>coord</code>和从Tensor起始位置搬出。传入<code>reg_tensor&lt;bool&gt;</code>，由<code>src</code>推导出<code>RegDataType</code>为<code>bool</code>。不支持双源操作数原型。</p><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><h3 id="矢量数据寄存器搬出-1">矢量数据寄存器搬出<a class="header-anchor" href="#矢量数据寄存器搬出-1">​</a></h3><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sideband_mode</td><td>搬出模式，类型为<code>store_sideband_mode</code>。单源操作数重载的默认值为<code>store_sideband_mode::direct</code>；双源操作数重载的默认值为<code>store_sideband_mode::intlv</code>。支持的模式请参考<a href="#%E8%A1%A83-store_sideband_mode%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表3</a>。</td></tr><tr><td>Tensor</td><td>目的Tensor类型，由函数实参自动推导。Tensor必须位于UB。</td></tr><tr><td>Coord</td><td>目的Tensor的坐标类型，由函数实参自动推导。</td></tr><tr><td>RegDataType</td><td>源寄存器元素类型，由函数实参自动推导。与目的Tensor的元素类型一致，但目的Tensor的元素类型为<code>int4b_t</code>时，源寄存器的元素类型为<code>int4x2_t</code>。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>tensor</td><td>输出</td><td>目的Tensor，必须位于UB。</td></tr><tr><td>coord</td><td>输入</td><td>搬出起始元素在<code>tensor</code>逻辑布局中的坐标。</td></tr><tr><td>src</td><td>输入</td><td>单源操作数重载的源寄存器。<code>direct</code>、<code>pack</code>和<code>pack_quarter</code>使用<code>src.mask</code>筛选有效元素，<code>store_1st</code>忽略<code>src.mask</code>。</td></tr><tr><td>src0</td><td>输入</td><td><code>intlv</code>模式的第一个源寄存器。该模式忽略<code>src0.mask</code>。</td></tr><tr><td>src1</td><td>输入</td><td><code>intlv</code>模式的第二个源寄存器。该模式忽略<code>src1.mask</code>。</td></tr></tbody></table><p><a id="表3-store_sideband_mode参数说明"></a></p><p><strong>表3</strong> 矢量数据寄存器搬出模式</p><p>表中的VL表示一个矢量数据寄存器的长度，单位为Byte。<code>int4b_t</code>类型的数据在寄存器中以<code>int4x2_t</code>形式存储。<code>int4x2_t</code>数据类型由两个四位整型数打包为一个8比特存储单元，<code>fp4x2_e2m1_t</code>和<code>fp4x2_e1m2_t</code>数据类型由两个独立的四位浮点数打包为一个8比特存储单元，因此，对于这三种类型，下表所述的“元素”是指一个8比特对应的搬运单元，而不是单个4比特值。</p><table><thead><tr><th>取值</th><th>含义</th><th>搬出起始地址对齐约束（Byte）</th></tr></thead><tbody><tr><td>store_sideband_mode::direct</td><td>正常模式，根据<code>src.mask</code>将源寄存器中的有效元素连续写入UB中的对应位置。</td><td>32</td></tr><tr><td>store_sideband_mode::store_1st</td><td>仅将<code>src</code>的第一个元素写入UB，忽略<code>src.mask</code>。</td><td><code>sizeof(RegDataType)</code></td></tr><tr><td>store_sideband_mode::intlv</td><td>交织模式，将<code>src0</code>和<code>src1</code>中的元素交替写入UB，得到2*VL数据量，忽略两个源操作数的<code>mask</code>。仅支持双源操作数重载。</td><td>32</td></tr><tr><td>store_sideband_mode::pack</td><td>2倍压缩模式，根据<code>src.mask</code>筛选有效元素，将每个有效元素的低半部分bit写入压缩后的位置。</td><td>min(32, VL/2)</td></tr><tr><td>store_sideband_mode::pack_quarter</td><td>4倍压缩模式，根据<code>src.mask</code>筛选有效元素，将每个有效32bit元素的低8bit写入压缩后的位置。</td><td>min(32, VL/4)</td></tr></tbody></table><h3 id="掩码寄存器搬出-1">掩码寄存器搬出<a class="header-anchor" href="#掩码寄存器搬出-1">​</a></h3><p><strong>表4</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sideband_mode</td><td>搬出模式，类型为<code>store_sideband_mode</code>，默认值为<code>store_sideband_mode::direct</code>。支持的模式请参考<a href="#%E8%A1%A86-%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA%E6%A8%A1%E5%BC%8F">表6</a>。</td></tr><tr><td>Tensor</td><td>目的Tensor类型，由函数实参自动推导。Tensor必须位于UB，支持的元素类型请参考<a href="#%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA-2">数据类型</a>。</td></tr><tr><td>Coord</td><td>目的Tensor的坐标类型，由函数实参自动推导。</td></tr><tr><td>RegDataType</td><td>源寄存器元素类型，从<code>reg_tensor&lt;bool&gt;</code>实参推导为<code>bool</code>。</td></tr></tbody></table><p><strong>表5</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>tensor</td><td>输出</td><td>用于存放掩码比特的UB Tensor。</td></tr><tr><td>coord</td><td>输入</td><td>搬出起始元素在<code>tensor</code>逻辑布局中的坐标。</td></tr><tr><td>src</td><td>输入</td><td>类型为<code>reg_tensor&lt;bool&gt;</code>。仅搬出<code>src.reg</code>中的掩码比特，不读取<code>src.mask</code>。</td></tr></tbody></table><p><a id="表6-掩码寄存器搬出模式"></a></p><p><strong>表6</strong> 掩码寄存器搬出模式</p><p>掩码比特连续写入UB，不会转换为逐元素的布尔值。VL为256字节时，掩码寄存器的长度为VL/8，即32字节。</p><table><thead><tr><th>取值</th><th>含义</th><th>UB写入量（Byte）</th><th>搬出起始地址对齐约束（Byte）</th></tr></thead><tbody><tr><td>store_sideband_mode::direct</td><td>按原样写入<code>src.reg</code>中的全部比特。</td><td>VL/8（32）</td><td>32</td></tr><tr><td>store_sideband_mode::pack</td><td>保留<code>src.reg</code>中偶数索引（从0开始）的比特，按顺序连续写入。</td><td>VL/16（16）</td><td>16</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><h3 id="矢量数据寄存器搬出-2">矢量数据寄存器搬出<a class="header-anchor" href="#矢量数据寄存器搬出-2">​</a></h3><p>支持的目的Tensor元素类型如下。未列出的类型或模式组合会产生编译期错误。其中，源寄存器类型为<code>reg_tensor&lt;int4x2_t&gt;</code>时，目的Tensor对应的数据类型为<code>int4b_t</code>。</p><table><thead><tr><th>sideband_mode</th><th>支持的数据类型</th></tr></thead><tbody><tr><td>direct、store_1st</td><td><code>int4b_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code></td></tr><tr><td>intlv</td><td><code>int4b_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code></td></tr><tr><td>pack</td><td><code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>、<code>int64_t</code></td></tr><tr><td>pack_quarter</td><td><code>int32_t</code>、<code>uint32_t</code>、<code>float</code></td></tr></tbody></table><h3 id="掩码寄存器搬出-2">掩码寄存器搬出<a class="header-anchor" href="#掩码寄存器搬出-2">​</a></h3><p>源寄存器元素类型为<code>bool</code>，目的Tensor的元素类型仅支持<code>uint8_t</code>、<code>uint16_t</code>和<code>uint32_t</code>。支持的模式请参考<a href="#%E8%A1%A86-%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA%E6%A8%A1%E5%BC%8F">表6</a>。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>两类搬出均无返回值。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>仅支持位于UB的Tensor。</li><li>实际搬出起始地址必须满足<a href="#%E8%A1%A83-store_sideband_mode%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表3</a>或<a href="#%E8%A1%A86-%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA%E6%A8%A1%E5%BC%8F">表6</a>中的对齐约束。</li><li>传入<code>coord</code>时，坐标维数必须与Tensor布局匹配，且坐标不能越界。</li><li>单源操作数重载不支持<code>store_sideband_mode::intlv</code>；双源操作数重载仅支持<code>store_sideband_mode::intlv</code>。</li><li>矢量数据寄存器搬出时，<code>direct</code>、<code>pack</code>和<code>pack_quarter</code>模式要求<code>src.reg</code>和<code>src.mask</code>均已初始化；<code>store_1st</code>和<code>intlv</code>模式仅要求参与搬出的<code>reg</code>成员已初始化。</li><li>矢量数据寄存器以<code>direct</code>模式搬出时，如果目的UB的剩余空间不足一个VL，必须通过<code>src.mask</code>关闭越界位置，并保证目的UB至少剩余一个DataBlock（32B）空间。</li><li>掩码寄存器搬出时，仅需初始化<code>src.reg</code>。目的Tensor的UB缓冲区必须能容纳<a href="#%E8%A1%A86-%E6%8E%A9%E7%A0%81%E5%AF%84%E5%AD%98%E5%99%A8%E6%90%AC%E5%87%BA%E6%A8%A1%E5%BC%8F">表6</a>所列的完整写入量，不能通过<code>src.mask</code>缩减写入范围。</li><li>寄存器数据搬出应在<code>__simd_vf__</code>函数或<code>__simd_callee__</code>函数中完成。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><h3 id="正常搬出">正常搬出<a class="header-anchor" href="#正常搬出">​</a></h3><p>以下示例将源Tensor搬入寄存器，绑定全有效mask后写入目的Tensor。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/mask_reg_compute.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/reg_data_load.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/reg_data_store.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadAndStore</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">coord</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>
<span class="w">    </span><span class="n">value</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><h3 id="交织搬出">交织搬出<a class="header-anchor" href="#交织搬出">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">StoreInterleaved</span><span class="p">(</span>
<span class="w">    </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">even</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">odd</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store_sideband_mode</span><span class="o">::</span><span class="n">intlv</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">even</span><span class="p">,</span><span class="w"> </span><span class="n">odd</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><h3 id="掩码寄存器搬出-3">掩码寄存器搬出<a class="header-anchor" href="#掩码寄存器搬出-3">​</a></h3><p>以下示例将同一个掩码分别搬出到两个UB Tensor。两个Tensor的元素类型均可为<code>uint8_t</code>、<code>uint16_t</code>或<code>uint32_t</code>。<code>direct_dst</code>须按32字节对齐且至少包含32字节，<code>packed_dst</code>须按16字节对齐且至少包含16字节。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">DirectTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">PackedTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">StoreMask</span><span class="p">(</span><span class="n">DirectTensor</span><span class="w"> </span><span class="n">direct_dst</span><span class="p">,</span><span class="w"> </span><span class="n">PackedTensor</span><span class="w"> </span><span class="n">packed_dst</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="o">::</span><span class="nn">experimental</span><span class="p">;</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">store</span><span class="p">(</span><span class="n">direct_dst</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="n">store</span><span class="o">&lt;</span><span class="n">store_sideband_mode</span><span class="o">::</span><span class="n">pack</span><span class="o">&gt;</span><span class="p">(</span><span class="n">packed_dst</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const m=a(e,[["render",l]]);export{_ as __pageData,m as default};
